package me.youngjibbit.notifications;
import org.junit.*;
import org.junit.rules.TemporaryFolder;
import java.util.*;
import static org.junit.Assert.*;
public class NotificationTimelineTest {
 @Rule public TemporaryFolder folder=new TemporaryFolder();
 @Before public void clear(){NotificationManager.drain();}
 @After public void after(){NotificationManager.drain();}
 NotificationManager.Message message(String text){return new NotificationManager.Message(new Notification(NotificationType.INFO,"Title",text,0));}
 @Test public void workerInboxIsBoundedAndCoalesces()throws Exception{Thread worker=new Thread(()->{for(int i=0;i<2000;i++)NotificationManager.show(new Notification(NotificationType.INFO,"Item","body "+i,0));});worker.start();worker.join();assertEquals(64,NotificationManager.inboxSize());NotificationManager.drain();worker=new Thread(()->{for(int i=0;i<100;i++)NotificationManager.show(new Notification(NotificationType.ERROR,"Repeated","Details",0));});worker.start();worker.join();List<NotificationManager.Message> messages=NotificationManager.drain();assertEquals(1,messages.size());assertEquals(100,messages.get(0).count);}
 @Test public void pendingLifetimeBeginsOnlyOnPromotion(){NotificationManager.Timeline model=new NotificationManager.Timeline();model.advance(Arrays.asList(message("first"),message("second")),0,0,1,4,5,false,t->true);assertEquals(1,model.visible.size());assertEquals(1,model.pending.size());model.advance(Collections.emptyList(),6000000000L,1,1,4,5,false,t->true);assertEquals("second",model.visible.get(0).notification.message);assertEquals(11000000000L,model.visible.get(0).expires);}
 @Test public void repeatedExitingEntryReversesWithoutResettingAlpha(){NotificationManager.Timeline model=new NotificationManager.Timeline();model.advance(Collections.singletonList(message("same")),0,0,3,4,1,true,t->true);model.advance(Collections.emptyList(),500000000L,.1f,3,4,1,true,t->true);float showing=model.visible.get(0).alpha;model.advance(Collections.emptyList(),1100000000L,.02f,3,4,1,true,t->true);float leaving=model.visible.get(0).alpha;assertTrue(leaving<showing);model.advance(Collections.singletonList(message("same")),1200000000L,.02f,3,4,1,true,t->true);assertEquals(1,model.visible.size());assertEquals(2,model.visible.get(0).count);assertTrue(model.visible.get(0).alpha>leaving);}
 @Test public void filtersLimitsAndReducedMotionApplyImmediately(){NotificationManager.Timeline model=new NotificationManager.Timeline();List<NotificationManager.Message> messages=new ArrayList<>();for(int i=0;i<100;i++)messages.add(message(""+i));model.advance(messages,0,.1f,2,4,5,false,t->true);assertEquals(2,model.visible.size());assertTrue(model.pending.size()<=4);assertEquals(1,model.visible.get(0).alpha,0);model.advance(Collections.emptyList(),1,.1f,2,4,5,false,t->false);assertTrue(model.visible.isEmpty());assertTrue(model.pending.isEmpty());}
 @Test public void actualConfigResultsEmitGenericFeedback()throws Exception{me.youngjibbit.config.ConfigManager manager=new me.youngjibbit.config.ConfigManager(folder.newFolder().toPath(),Collections.emptyList(),()->false,s->{});assertTrue(manager.saveConfig("named"));List<NotificationManager.Message> saved=NotificationManager.drain();assertEquals(1,saved.size());assertEquals(NotificationType.SUCCESS,saved.get(0).notification.type);assertTrue(manager.loadConfig("named"));assertEquals(NotificationType.SUCCESS,NotificationManager.drain().get(0).notification.type);assertFalse(manager.loadConfig("missing"));List<NotificationManager.Message> failure=NotificationManager.drain();assertEquals(1,failure.size());assertEquals(NotificationType.ERROR,failure.get(0).notification.type);assertFalse(failure.get(0).notification.message.contains("missing"));assertFalse(manager.saveConfig("../escape"));assertEquals(NotificationType.ERROR,NotificationManager.drain().get(0).notification.type);}
 @Test public void payloadsAreBoundedAndControlCharactersRemoved(){Notification n=new Notification(NotificationType.INFO,"a\t\u0000b","line1\nline2",100);assertEquals("ab",n.title);assertEquals("line1\nline2",n.message);assertEquals(15,n.seconds);}
}
